import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十章","description":"《正易心法》第三十章——二十四爻，求之八卦：384 爻中 360 为正爻配平年、24 为叠数配闰月；其数来自八纯卦上下相叠之重复，故闰数不只见于数，亦见于象。","frontmatter":{"title":"正易心法·第三十章","description":"《正易心法》第三十章——二十四爻，求之八卦：384 爻中 360 为正爻配平年、24 为叠数配闰月；其数来自八纯卦上下相叠之重复，故闰数不只见于数，亦见于象。","category":"guide","aliases":["正易心法第三十章","二十四爻求之八卦","叠数与闰数"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-30.md","filePath":"yijing/zheng-yi-xin-fa/chapter-30.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-30.md"},x=p({...c,setup(u){const i=[{id:"z30-01",label:"一、二十四爻之求",showLabel:!0,sentences:[["二十四爻，求之八卦。画纯为",{text:"叠",glossary:"die"},"，是为",{text:"闰数",glossary:"runshu"},"。"]],note:["多出的二十四爻，要从八卦的卦画中去寻求；画成纯卦（上下相叠）就是重叠之数，这就是闰数。（**本章接着第二十九章往下走**：第二十九章说「384 与含闰阴历年吻合」（外部印证），本章说「这多出来的 24 爻从哪里来」（内部推导）。**两章合读：外与内同时指向 384，才不是附会。**）"]},{id:"z30-02",label:"二、二十四为余",showLabel:!0,sentences:[["一岁三百六十，而爻数三百八十四，则是二十四爻为余也。以卦画求之，是为叠数。"]],note:["一年三百六十天，而爻数有三百八十四，那么多出来的二十四爻就是余数；从卦画来寻求，这是重叠之数。（**384 − 360 = 24**：麻衣把 360 爻定为「正爻」（配平年），把 24 爻定为「叠数」（配闰月）。**问题随之而来：这 24 爻，从卦画的哪个地方来？**）"]},{id:"z30-03",label:"三、八卦合体",showLabel:!0,sentences:[["何以言之？夫既有八卦矣。及八卦互相合体，以立诸卦。则诸卦者，八卦在其中矣。"]],note:["为什么这样说？已经有了八卦，八卦互相合体，组成各卦（六十四卦）；那么各卦之中，八卦都已经在其中了。（**这一句是为「叠」作准备**：56 个非纯卦里，上下卦各不相同，八卦各出现一次，**没有重复**——所以这 56 卦的爻数是「正常」的部分。）"]},{id:"z30-04",label:"四、八纯卦之叠",showLabel:!0,sentences:[["而别又有",{text:"八纯卦",glossary:"baChungua"},"，则其合体八卦为",{text:"重复",glossary:"chongfu"},"，而二十四数为叠也。"]],note:["而另外又有八个纯卦（上下卦相同），那么这八个纯卦的合体就是重复，二十四爻就是重叠之数。（**八纯卦就是乾、坤、坎、离、震、艮、巽、兑这八卦的重卦**——它们上下相叠，其中有一组三爻是「重复」出来的，**8 × 3＝24，正是那个余数。** 已在 56 个非纯卦中出现过的八卦，在这里又叠了一次。）"]},{id:"z30-05",label:"五、正爻与闰数",showLabel:!0,sentences:[["是以三百六十为正爻，与每岁之数合。而三百八十四，与闰岁之数合矣，则是闰数也。"]],note:["因此三百六十爻是正爻，与每岁（平年）的天数相合；而三百八十四爻，与闰年的天数相合——这就是闰数。（**关系很清楚**：正爻（360）＝平年＝常规运行；叠爻（24）＝闰月＝盈余积累；**合计（384）＝闰年＝完整周期。**）"]},{id:"z30-06",label:"六、见于数与象",showLabel:!0,sentences:[["岂惟见于数，亦见于象。人知之",{text:"该鲜",glossary:"gaiXian"},"矣。"]],note:["这个道理不只见于数，也见于象。知道这个道理的人，大概很少了。（**见于数**：384 − 360 = 24，8 纯卦 × 3 叠爻 = 24。**见于象**：八纯卦在象上就是「上下相同＝相叠」的样子，而闰月正是「正常年份之外叠加出来的时间」——**两者在象上都是「叠」。** 麻衣在此点到为止，未及展开。）"]}],o=[{id:"die",term:"叠",pinyin:"dié",meaning:"重叠。八纯卦上下卦相同，爻数重复，多出 24 爻，故为叠数。"},{id:"runshu",term:"闰数",pinyin:"rùn shù",meaning:"对应闰月的数。384 − 360 = 24，这 24 爻正是闰月的象数来源。"},{id:"baChungua",term:"八纯卦",pinyin:"bā chún guà",meaning:"上下卦相同的八卦：乾、坤、坎、离、震、艮、巽、兑（重卦）。"},{id:"chongfu",term:"重复",pinyin:"chóng fù",meaning:"重复出现。八纯卦的上下卦与原八卦重复。"},{id:"gaiXian",term:"该鲜",pinyin:"gāi xiǎn",meaning:"大概很少。「该」大约、大概，「鲜」少。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",21)),e(r,{colophon:"二十四爻 · 画纯为叠 · 正爻与闰数 · 见于数与象",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"叠数",pinyin:["dié","shù"],meaning:"八纯卦上下卦相同，爻数重复，多出的 24 爻即叠数——384 − 360 = 24。"},{term:"八纯卦",pinyin:["bā","chún"],meaning:"上下卦相同的八卦：乾、坤、坎、离、震、艮、巽、兑。每个纯卦有 3 爻是「叠」出来的。"},{term:"正爻与闰数",pinyin:["zhèng","yáo"],meaning:"360 为正爻（配平年），384 与闰年之数合——24 叠爻即闰月的象数来源。"},{term:"叠（象）",pinyin:["dié"],meaning:"纯卦在象上是「上下相叠」，闰月在时间上是「叠加出来的一个月」，两者同为一个「叠」。"},{term:"该鲜",pinyin:["gāi","xiǎn"],meaning:"大概很少。「该」大约，「鲜」少。麻衣在此点到为止，未及展开「见于象」的部分。"}]}),n[3]||(n[3]=t("",25))])}}});export{y as __pageData,x as default};
